do $post$
declare opt uuid:='144042c1-e493-4256-a86c-cd088a8898ce'; sf uuid:='20cd72aa-f281-4985-931b-a83422404b66';
begin
  if (select count(*) from public.contpaq_accounts where company_id=opt)<>1646 then raise exception 'contpaq_seed_opt_accounts_count'; end if;
  if (select count(*) from public.contpaq_accounts where company_id=sf)<>694 then raise exception 'contpaq_seed_sf_accounts_count'; end if;
  if (select count(*) from public.account_report_lines where company_id=opt)<>95 then raise exception 'contpaq_seed_opt_lines_count'; end if;
  if (select count(*) from public.account_report_lines where company_id=sf)<>396 then raise exception 'contpaq_seed_sf_lines_count'; end if;
  if (select count(*) from public.contpaq_terceros where company_id=opt)<>187 then raise exception 'contpaq_seed_opt_terceros_count'; end if;
  if (select count(*) from public.budget_account_mappings where company_id=opt)<>87 then raise exception 'contpaq_seed_opt_maps_count'; end if;
  if (select count(*) from public.budget_account_mappings where company_id=sf)<>60 then raise exception 'contpaq_seed_sf_maps_count'; end if;
  if (select count(*) from public.budget_account_mappings where company_id=opt and needs_review)<>6 then raise exception 'contpaq_seed_opt_review_count'; end if;
  if (select count(*) from public.budget_account_mappings where company_id=sf and needs_review)<>18 then raise exception 'contpaq_seed_sf_review_count'; end if;
  if (select count(*) from public.tax_account_mappings where company_id=opt)<>6 then raise exception 'contpaq_seed_opt_tax_count'; end if;
  if exists(select 1 from public.budget_account_mappings m left join public.contpaq_accounts a on a.company_id=m.company_id and a.code=m.contpaq_account_code where a.code is null or not a.is_detail or not a.activo) then raise exception 'contpaq_seed_invalid_mapping_account'; end if;
end
$post$;
commit;
